import{_ as s,C as n,o as r,c as i,a3 as l,E as c,w as p,j as t,a as o}from"./chunks/framework.cycUHubK.js";const k=JSON.parse('{"title":"Projects & Snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/projects-and-snapshots.md","filePath":"concepts/projects-and-snapshots.md"}'),d={name:"concepts/projects-and-snapshots.md"};function h(u,e,g,m,f,j){const a=n("ManualRelated");return r(),i("div",null,[e[1]||(e[1]=l('<h1 id="projects-snapshots" tabindex="-1">Projects &amp; Snapshots <a class="header-anchor" href="#projects-snapshots" aria-label="Permalink to &quot;Projects &amp; Snapshots&quot;">​</a></h1><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><p>A <strong>project</strong> holds everything about one performance setup:</p><ul><li>32 knobs and all macro mappings</li><li>Up to <strong>8 racks</strong> (MIDI device chains)</li><li>16 LFO configurations and assignments</li><li>Snapshots for scene recall within the project</li><li>Clock source and BPM, default MIDI channel, and encoder-button shortcut</li></ul><p>Use <strong>Main Menu → Project → Library</strong> to create, load, rename, or delete projects. Clock, channel, and encoder live under <strong>Project Settings</strong>. See <a href="./../projects/">Project</a> for save and list workflows.</p><p>Note names (Middle C as C3 or C4), MIDI Thru, contrast, firmware, and bulk migrate stay on <strong>this S32</strong> under <a href="./../settings/">Settings</a>.</p><p><strong>Typical workflow:</strong></p><ol><li>Create or load a project from <strong>Main Menu → Project → Library</strong>.</li><li>Set clock, channel, and encoder under <strong>Project Settings</strong>.</li><li>Build racks, macros, and LFO routing.</li><li><strong>Save Project</strong> when you want changes to survive power-off.</li><li>Use <strong>Save As</strong> on the Library side menu to fork a copy under a new name.</li></ol><p>Switching projects with unsaved edits may prompt you to save or discard. Loading a project applies its clock and channel and <strong>stops</strong> transport.</p><h2 id="snapshot" tabindex="-1">Snapshot <a class="header-anchor" href="#snapshot" aria-label="Permalink to &quot;Snapshot&quot;">​</a></h2><p>A snapshot captures the <strong>current state</strong> of the active project — knob values, device parameters, bypass states — for instant recall during a set.</p><p><strong>Use snapshots when:</strong></p><ul><li>You need fast scene changes (intro / drop / outro) within one project.</li><li>You want to experiment, then jump back to a known point.</li></ul><p><strong>Use Save Project when:</strong></p><ul><li>You changed structure (new devices, macro modes, LFO wiring) or Project Settings and want it after power off.</li></ul><div class="warning custom-block"><p class="custom-block-title">Coming soon</p><p>Full snapshot documentation (list, take, recall, rename, delete) is being updated for the latest firmware. See <a href="./../snapshots/">Snapshots</a> for the menu location.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li>Build and <strong>Save Project</strong> once per song or set.</li><li>Use <strong>snapshots</strong> for sections within that set.</li><li><strong>Save As</strong> on the Library to fork a variation under another name.</li></ol></div>',17)),c(a,null,{default:p(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"./../projects/"},"Project"),o(" — Create, load, rename, and save projects")]),t("li",null,[t("a",{href:"./../snapshots/"},"Snapshots"),o(" — Snapshot menu location")]),t("li",null,[t("a",{href:"./rack-chains"},"Rack chains"),o(" — Racks and device chains in a project")])],-1)])]),_:1})])}const v=s(d,[["render",h]]);export{k as __pageData,v as default};
